package com.classsync.controller;
import com.classsync.entity.*; import com.classsync.repository.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*;
import org.springframework.transaction.annotation.Transactional;
@RestController @RequestMapping("/api/events") public class EventController {
 private final CalendarEventRepository repo;private final SubjectRepository subjects;private final UserRepository users;public EventController(CalendarEventRepository r,SubjectRepository s,UserRepository u){repo=r;subjects=s;users=u;}
 public record Input(@NotBlank @Size(max=180) String title,String description,CalendarEvent.EventType eventType,@NotNull Instant startAt,@NotNull Instant endAt,String location,Long subjectId){} public record View(Long id,String title,String description,String eventType,Instant startAt,Instant endAt,String location,Long subjectId,String subject){}
 @GetMapping public List<View> all(){return repo.findAllByOrderByStartAtAsc().stream().map(this::view).toList();}
 @GetMapping("/upcoming") public List<View> upcoming(){return repo.findByEndAtGreaterThanEqualOrderByStartAtAsc(Instant.now()).stream().limit(10).map(this::view).toList();}
 @PostMapping @PreAuthorize("hasRole('CR')") public View create(@Valid @RequestBody Input x,Authentication a){var e=new CalendarEvent();apply(e,x);e.setCreatedBy(users.findByEmailIgnoreCase(a.getName()).orElseThrow());return view(repo.save(e));}
 @PutMapping("/{id}") @PreAuthorize("hasRole('CR')") @Transactional public View update(@PathVariable Long id,@Valid @RequestBody Input x){var e=repo.findById(id).orElseThrow(()->new NoSuchElementException("Event not found"));apply(e,x);return view(repo.save(e));}
 @DeleteMapping("/{id}") @PreAuthorize("hasRole('CR')") public void delete(@PathVariable Long id){repo.deleteById(id);}
 @GetMapping(value="/{id}/ics",produces="text/calendar") public ResponseEntity<String> ics(@PathVariable Long id){var e=repo.findById(id).orElseThrow(()->new NoSuchElementException("Event not found"));String body="BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//ClassSync//EN\r\nBEGIN:VEVENT\r\nUID:event-"+e.getId()+"@classsync.local\r\nDTSTAMP:"+fmt(Instant.now())+"\r\nDTSTART:"+fmt(e.getStartAt())+"\r\nDTEND:"+fmt(e.getEndAt())+"\r\nSUMMARY:"+escape(e.getTitle())+"\r\nDESCRIPTION:"+escape(e.getDescription())+"\r\nLOCATION:"+escape(e.getLocation())+"\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n";return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=classsync-event-"+id+".ics").body(body);}
 private String fmt(Instant i){return DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss'Z'").withZone(ZoneOffset.UTC).format(i);} private String escape(String s){return s==null?"":s.replace("\\","\\\\").replace("\n","\\n").replace(",","\\,").replace(";","\\;");}
 private void apply(CalendarEvent e,Input x){if(!x.endAt().isAfter(x.startAt()))throw new IllegalArgumentException("End time must be after start time");e.setTitle(x.title().trim());e.setDescription(x.description());e.setEventType(x.eventType()==null?CalendarEvent.EventType.OTHER:x.eventType());e.setStartAt(x.startAt());e.setEndAt(x.endAt());e.setLocation(x.location());e.setSubject(x.subjectId()==null?null:subjects.findById(x.subjectId()).orElseThrow(()->new NoSuchElementException("Subject not found")));}
 private View view(CalendarEvent e){return new View(e.getId(),e.getTitle(),e.getDescription(),e.getEventType().name(),e.getStartAt(),e.getEndAt(),e.getLocation(),e.getSubject()==null?null:e.getSubject().getId(),e.getSubject()==null?null:e.getSubject().getName());}
}
